79	struct PreservePresence;
80	impl VisitMut for PreservePresence {
81	    fn visit_field_mut(&mut self, field: &mut syn::Field) {
82	        let mut optional = false;
83	        let mut kept = vec![];
84	        let mut attrs = vec![];
85	        for attr in &field.attrs {
86	            if attr.path().is_ident("serde") {
87	                let values = attr.parse_args_with(syn::punctuated::Punctuated::<syn::Meta, syn::Token![,]>::parse_terminated).unwrap();
88	                for value in values {
89	                    if value.path().is_ident("default") || value.path().is_ident("skip_serializing_if") {
90	                        optional = true;
91	                    } else { kept.push(value); }
92	                }
93	            } else { attrs.push(attr.clone()); }
94	        }
95	        if optional {
96	            let inner = &field.ty;
97	            field.ty = syn::parse_quote!(FieldPresence<#inner>);
98	            kept.push(syn::parse_quote!(default));
99	            kept.push(syn::parse_quote!(skip_serializing_if = "FieldPresence::is_missing"));
100	        }
101	        if !kept.is_empty() { attrs.push(syn::parse_quote!(#[serde(#(#kept),*)])); }
102	        field.attrs = attrs;
103	    }
104	}
