107	impl<'ast> Visit<'ast> for Names {
108	    fn visit_type_path(&mut self, node: &'ast syn::TypePath) {
109	        if let Some(segment) = node.path.segments.last() { self.0.push(segment.ident.to_string()); }
110	        syn::visit::visit_type_path(self, node);
111	    }
112	    fn visit_path(&mut self, node: &'ast syn::Path) {
113	        for segment in &node.segments { self.0.push(segment.ident.to_string()); }
114	        syn::visit::visit_path(self, node);
115	    }
116	}
