20	    // before any JS number parsing. Never reconstruct numeric literals here.
21	    if (Object.hasOwn(node, 'tsType')) return '('+node.tsType+')';
22	    const constraints = [];
23	    if (node.$ref !== undefined) {
24	      const prefix = '#/definitions/';
25	      if (typeof node.$ref !== 'string' || !node.$ref.startsWith(prefix)) throw new Error('unflattened reference');
26	      const name = node.$ref.slice(prefix.length);
27	      visit(name);
28	      constraints.push(name);
29	    }
30	    if (node.enum !== undefined) {
31	      if (node.enum.some(v=>typeof v==='number')) throw new Error('numeric enum without exact literal projection');
32	      constraints.push('('+node.enum.map(v=>json(v)).join(' | ')+')');
33	    }
34	    if (node.const !== undefined) throw new Error('const without exact literal projection');
35	    if (node.type !== undefined) {
36	      const types = Array.isArray(node.type) ? node.type : [node.type];
37	      constraints.push('('+types.map(kind=>{
38	        if (Object.hasOwn(scalar,kind)) return scalar[kind];
39	        if (kind==='array') return '('+expression(node.items === undefined ? true : node.items)+')[]';
40	        if (kind!=='object') throw new Error('unsupported carrier type: '+kind);
41	        const fields = [];
42	        const properties = node.properties || {};
43	        const required = new Set(node.required || []);
44	        for (const key of Object.keys(properties).sort()) {
45	          fields.push(json(key)+(required.has(key)?'':'?')+': '+expression(properties[key])+';');
46	        }
47	        for (const key of [...required].sort()) {
48	          if (!Object.hasOwn(properties,key)) fields.push(json(key)+': Json;');
49	        }
50	        // Pattern/extra-key restrictions remain runtime constraints. Combining
51	        // a typed index with fixed fields can wrongly narrow those fixed fields;
52	        // use Json for the index when both coexist, retaining each named field.
53	        const patterns = Object.values(node.patternProperties || {});
54	        let index;
55	        if (node.additionalProperties !== false) index = node.additionalProperties === undefined ? 'Json' : expression(node.additionalProperties);
56	        if (patterns.length) index = [index, ...patterns.map(expression)].filter(Boolean).join(' | ');
