fn main() {
 let root=std::path::PathBuf::from(std::env::args().nth(1).unwrap());
 let data:serde_json::Value=serde_json::from_slice(&std::fs::read(root.join("carrier-cases.json")).unwrap()).unwrap();
 let mut failures=vec![];
 for row in data["rows"].as_array().unwrap() {
  let reference=row[0].as_str().unwrap();let i=row[1].as_u64().unwrap() as usize; let v=&data["values"][i];
  match check(reference,v) {
   Ok(x) if x==*v=>{},
   Ok(x)=>failures.push(serde_json::json!({"ref":reference,"index":i,"roundtrip":x,"original":v})),
   Err(e)=>failures.push(serde_json::json!({"ref":reference,"index":i,"error":e})),
  }
 }
 let out=serde_json::json!({"rows":data["rows"].as_array().unwrap().len(),"failures":failures});
 std::fs::write(root.join("carrier-differential.json"),serde_json::to_vec_pretty(&out).unwrap()).unwrap();
 println!("rows={}, failures={}",out["rows"],out["failures"].as_array().unwrap().len());
 assert!(out["failures"].as_array().unwrap().is_empty());
}
